export const TOOL_CATALOG_BY_SLUG: ReadonlyMap<string, ToolCatalogEntry> =
  new Map(TOOL_CATALOG.map((tool) => [tool.slug, tool]));

export function getToolBySlug(slug: string): ToolCatalogEntry | undefined {
  return TOOL_CATALOG_BY_SLUG.get(slug);
}

export function getAllToolSlugs(): string[] {
  return TOOL_CATALOG.map((tool) => tool.slug);
}

export function getToolsByCategory(category: string): ToolCatalogEntry[] {
  return TOOL_CATALOG.filter((tool) => tool.category === category);
}

export function getAllCategories(): string[] {
  return Array.from(new Set(TOOL_CATALOG.map((tool) => tool.category)));
}
